def execute(arguments):
    """
    剪贴板操作

    参数:
        arguments (dict): 包含以下字段
            - operation (str): 操作类型
                - "read": 读取剪贴板内容
                - "write": 写入剪贴板内容
            - text (str): 要写入的文本，write操作必填

    返回:
        dict: 包含操作结果的字典
            - success (bool): 是否成功
            - text (str): 剪贴板内容（read操作）
            - error (str): 错误信息（失败时）
    """
    import subprocess
    import platform

    operation = arguments.get("operation", "read")
    text = arguments.get("text", "")

    try:
        is_windows = platform.system() == "Windows"

        if operation == "read":
            if is_windows:
                result = subprocess.run(
                    ["powershell", "-command", "Get-Clipboard"],
                    capture_output=True,
                    text=True
                )
                return {
                    "success": True,
                    "text": result.stdout.strip()
                }
            else:
                result = subprocess.run(
                    ["xclip", "-selection", "clipboard", "-o"],
                    capture_output=True,
                    text=True
                )
                return {
                    "success": True,
                    "text": result.stdout
                }

        elif operation == "write":
            if not text:
                return {"success": False, "error": "请提供要写入的文本"}

            if is_windows:
                subprocess.run(
                    ["powershell", "-command", f"Set-Clipboard -Value '{text}'"],
                    capture_output=True
                )
                return {
                    "success": True,
                    "text": text
                }
            else:
                subprocess.run(
                    ["xclip", "-selection", "clipboard"],
                    input=text.encode(),
                    capture_output=True
                )
                return {
                    "success": True,
                    "text": text
                }

        else:
            return {"success": False, "error": f"未知的操作: {operation}"}
    except FileNotFoundError:
        return {"success": False, "error": "剪贴板工具未安装（Linux需要xclip）"}
    except Exception as e:
        return {"success": False, "error": f"操作失败: {str(e)}"}
